/*
 * generated by Xtext 2.30.0
 *
 * Headless entry point extended by Wodel to support an explicit project/output
 * directory. The first argument remains the Wodel resource path for backwards
 * compatibility; the optional second argument is the Wodel project directory.
 */
package wodel.dsls.runner;

import com.google.inject.Inject;
import com.google.inject.Injector;
import com.google.inject.Provider;

import mutatorenvironment.MutatorEnvironment;
import mutatorenvironment.MutatorenvironmentPackage;
import mutatorenvironment.Program;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collection;
import java.util.Map;

import org.eclipse.emf.common.util.URI;
import org.eclipse.emf.ecore.EObject;
import org.eclipse.emf.ecore.EPackage;
import org.eclipse.emf.ecore.EStructuralFeature;
import org.eclipse.emf.ecore.resource.Resource;
import org.eclipse.emf.ecore.resource.ResourceSet;
import org.eclipse.emf.ecore.resource.impl.ResourceSetImpl;
import org.eclipse.emf.ecore.util.EcoreUtil;
import org.eclipse.emf.ecore.xmi.impl.EcoreResourceFactoryImpl;
import org.eclipse.emf.ecore.xmi.impl.XMIResourceFactoryImpl;
import org.eclipse.xtext.generator.GeneratorContext;
import org.eclipse.xtext.generator.GeneratorDelegate;
import org.eclipse.xtext.generator.JavaIoFileSystemAccess;
import org.eclipse.xtext.util.CancelIndicator;
import org.eclipse.xtext.validation.IResourceValidator;
import wodel.dsls.WodelStandaloneSetup;

import wodel.dsls.runner.WodelSemanticCodeGenerator;


public class WodelRunner {

	/**
	 * Prefer a platform:/resource URI when the project is present in the active
	 * Eclipse workspace. This lets all Wodel generators recover the IProject from
	 * the semantic Resource without UI-global project state.
	 */
	public static void main(String[] args) {
		if (args.length == 0) {
			System.err.println("Aborting: no path to Wodel resource provided!");
			return;
		}
		Injector injector = new WodelStandaloneSetup().createInjectorAndDoEMFRegistration();
		WodelRunner main = injector.getInstance(WodelRunner.class);
		String projectPath = args.length > 1 ? args[1] : null;
		main.runGenerator(args[0], projectPath);
	}

	@Inject
	private Provider<ResourceSet> resourceSetProvider;

	@Inject
	private IResourceValidator validator;

	@Inject
	private GeneratorDelegate generator;

	@Inject
	private JavaIoFileSystemAccess fileAccess;
	
	@Inject
	private WodelSemanticCodeGenerator
	    semanticCodeGenerator;

	protected void runGenerator(String resourcePath) {
		runGenerator(resourcePath, null);
	}

	private void checkUnresolvedProxies(ResourceSet set) {

		Map<EObject, Collection<EStructuralFeature.Setting>> unresolved = EcoreUtil.UnresolvedProxyCrossReferencer
				.find(set);

		if (unresolved.isEmpty()) {
			return;
		}

		System.err.println("Unresolved Wodel references: " + unresolved.size());

		int count = 0;

		for (EObject proxy : unresolved.keySet()) {

			System.err.println("  " + EcoreUtil.getURI(proxy));

			if (++count >= 10) {
				break;
			}
		}

		throw new IllegalStateException(
				"The Wodel semantic model contains " + unresolved.size() + " unresolved reference(s).");
	}

	protected void runGenerator(String resourcePath, String projectPath) {
		try {

			Path modelFile = Paths.get(resourcePath).toAbsolutePath().normalize();

			if (!Files.isRegularFile(modelFile)) {
				throw new IllegalArgumentException("Wodel semantic model does not exist: " + modelFile);
			}

			ResourceSet set = new ResourceSetImpl();

			/*
			 * Wodel semantic metamodel.
			 */
			set.getPackageRegistry().put(MutatorenvironmentPackage.eNS_URI, MutatorenvironmentPackage.eINSTANCE);

			/*
			 * IMPORTANT:
			 *
			 * Register exact extensions. Do not use "*" or DEFAULT_EXTENSION.
			 */
			set.getResourceFactoryRegistry().getExtensionToFactoryMap().put("model", new XMIResourceFactoryImpl());

			set.getResourceFactoryRegistry().getExtensionToFactoryMap().put("ecore", new EcoreResourceFactoryImpl());

			/*
			 * Load the Wodel semantic model.
			 *
			 * At this stage references to the domain metamodel may still be proxies. That
			 * is okay.
			 */
			Resource resource = set.getResource(URI.createFileURI(modelFile.toString()), true);

			if (resource.getContents().isEmpty()) {
				throw new IllegalStateException("Empty Wodel model: " + modelFile);
			}

			EObject root = resource.getContents().get(0);

			if (!(root instanceof MutatorEnvironment)) {
				throw new IllegalStateException(
						"Expected MutatorEnvironment in " + modelFile + " but found " + root.eClass().getName());
			}

			MutatorEnvironment environment = (MutatorEnvironment) root;

			/*
			 * Before resolving all the references, load and register the example/domain
			 * Ecore metamodel.
			 */
			registerDomainMetamodel(set, environment, projectPath);

			/*
			 * Now EClass, EReference, EAttribute, etc. can be resolved.
			 */
			EcoreUtil.resolveAll(set);

			checkUnresolvedProxies(set);

			/*
			 * Generate Java directly from this semantic Resource.
			 *
			 * No deserialization to .mutator.
			 */
			WodelSemanticCodeGenerator.GenerationResult result =
				    semanticCodeGenerator.generateStandalone(
				        environment,
				        projectPath
				    );

				System.out.println(result);

		} catch (Exception e) {
			throw new IllegalStateException("Could not generate code directly " + "from Wodel .model", e);
		}
	}

	private void configureOutput(String projectPath) {

		if (projectPath == null || projectPath.isBlank()) {

			fileAccess.setOutputPath("src-gen/");

			return;
		}

		Path output = Paths.get(projectPath).toAbsolutePath().normalize().resolve("src-gen");

		fileAccess.setOutputPath(output.toString());
	}

	private void registerDomainMetamodel(ResourceSet set, MutatorEnvironment environment, String projectPath)
			throws IOException {

		if (!(environment.getDefinition() instanceof Program)) {

			throw new IllegalStateException("The MutatorEnvironment does not " + "contain a Wodel Program definition.");
		}

		Program program = (Program) environment.getDefinition();

		String metamodelValue = program.getMetamodel();

		if (metamodelValue == null || metamodelValue.isBlank()) {

			throw new IllegalStateException("The Wodel Program does not specify " + "a domain metamodel.");
		}

		Path metamodelPath = resolveMetamodelPath(metamodelValue, projectPath);

		if (!Files.isRegularFile(metamodelPath)) {

			throw new IOException("Domain metamodel not found: " + metamodelPath);
		}

		System.out.println("Loading domain metamodel: " + metamodelPath);

		Resource metamodelResource = set.getResource(URI.createFileURI(metamodelPath.toString()), true);

		for (EObject object : metamodelResource.getContents()) {

			if (object instanceof EPackage) {

				registerPackage(set, (EPackage) object);
			}
		}

		EcoreUtil.resolveAll(metamodelResource);
	}

	private void registerPackage(ResourceSet set, EPackage ePackage) {

		if (ePackage == null) {
			return;
		}

		String nsURI = ePackage.getNsURI();

		if (nsURI != null && !nsURI.isBlank()) {

			set.getPackageRegistry().put(nsURI, ePackage);

			System.out.println("Registered EPackage: " + ePackage.getName() + " -> " + nsURI);
		}

		for (EPackage subpackage : ePackage.getESubpackages()) {

			registerPackage(set, subpackage);
		}
	}

	private Path resolveMetamodelPath(String value, String projectPath) {

		String path = value.trim();

		if (path.startsWith("file:")) {

			return Paths.get(java.net.URI.create(path)).toAbsolutePath().normalize();
		}

		Path candidate = Paths.get(path);

		if (candidate.isAbsolute()) {
			return candidate.normalize();
		}

		if (projectPath != null && !projectPath.isBlank()) {

			Path project = Paths.get(projectPath).toAbsolutePath().normalize();

			/*
			 * First try relative to project.
			 */
			Path relative = project.resolve(candidate).normalize();

			if (Files.exists(relative)) {
				return relative;
			}

			/*
			 * Useful fallback when Program.metamodel contains only "python.ecore".
			 */
			Path dataModel = project.resolve("data").resolve("model").resolve(candidate.getFileName());

			if (Files.exists(dataModel)) {
				return dataModel.normalize();
			}
		}

		return candidate.toAbsolutePath().normalize();
	}
}